content.text:
export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryRule {
  category: string;
  minNights: number;
  maxNights: number;
  maxGuests: number;
  ratePerNight: number;
  highSurcharge: number;
  underMinError: string;
  extraGuestsFee?: number;
  flatFee?: number;
}

// One row holds everything that makes a category differ; the quoting logic
// itself is shared by every category.
const CATEGORIES: Record<string, CategoryRule> = {
  standard: {
    category: "standard",
    minNights: 1,
    maxNights: 14,
    maxGuests: 2,
    ratePerNight: 80,
    highSurcharge: 30,
    underMinError: "bad nights",
  },
  suite: {
    category: "suite",
    minNights: 1,
    maxNights: 21,
    maxGuests: 4,
    ratePerNight: 150,
    highSurcharge: 60,
    underMinError: "bad nights",
    extraGuestsFee: 25,
  },
  villa: {
    category: "villa",
    minNights: 3,
    maxNights: 28,
    maxGuests: 8,
    ratePerNight: 300,
    highSurcharge: 120,
    underMinError: "villa minimum stay",
    flatFee: 500,
  },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const loyalty = req.loyaltyYears as number;
  if (!Number.isInteger(req.loyaltyYears) || loyalty < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  if (!Object.prototype.hasOwnProperty.call(CATEGORIES, req.category as string)) {
    return { ok: false, error: "unknown category" };
  }
  const rule = CATEGORIES[req.category as string];
  const nights = req.nights as number;
  const guests = req.guests as number;
  const season = req.season as string;

  if (!Number.isInteger(nights) || nights < 1 || nights > rule.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (nights < rule.minNights) {
    return { ok: false, error: rule.underMinError };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > rule.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (season !== "low" && season !== "high") {
    return { ok: false, error: "bad season" };
  }

  let total = rule.ratePerNight * nights;
  if (season === "high") {
    total = total + rule.highSurcharge * nights;
  }
  const premier = req.coupon === "VIP" || loyalty >= 3;
  if (premier) {
    total = total - Math.floor(total / 10);
  }
  if (rule.extraGuestsFee && guests > 2) {
    total = total + rule.extraGuestsFee;
  }
  if (rule.flatFee) {
    total = total + rule.flatFee;
  }
  const policy = premier ? "flex" : "strict";
  const line = String(rule.category) + ":" + String(nights) + "n:" + String(total) + ":" + policy;
  return { ok: true, total, policy, line };
}

export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategoryRule {
  category: string;
  minNights: number;
  maxNights: number;
  maxGuests: number;
  ratePerNight: number;
  highSurcharge: number;
  underMinError: string;
  extraGuestsFee?: number;
  flatFee?: number;
}

